def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    border = max((v for v in counts if v != bg), key=lambda v: counts[v])
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, border)]
    out = [row[:] for row in grid]

    # Two border runs on opposite vertical sides: marker rows in one segment
    # paint the matching row of the other segment, and extend toward their edge.
    by_col = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == border:
                by_col.setdefault(c, []).append(r)
    vertical = [(c, sorted(rs)) for c, rs in by_col.items() if len(rs) >= 2]
    if len(vertical) >= 2:
        vertical.sort()
        c1, rs1 = vertical[0]
        c2, rs2 = vertical[-1]
        def segments(rows):
            groups=[]
            for r in rows:
                if not groups or r != groups[-1][-1] + 1:
                    groups.append([r])
                else:
                    groups[-1].append(r)
            return groups
        segs = [(c, s) for c,rs in ((c1,rs1),(c2,rs2)) for s in segments(rs)]
        # Typical layout has one run at each end, staggered vertically.
        if len(segs) >= 2:
            segs.sort(key=lambda x: x[1][0])
            (ca, a), (cb, b) = segs[0], segs[-1]
            for r, c, color in markers:
                source = b if b[0] <= r <= b[-1] else a if a[0] <= r <= a[-1] else None
                target = a if source is b else b if source is a else None
                if source is not None and target is not None:
                    rr = target[0] + (r - source[0])
                    if target[0] <= rr <= target[-1]:
                        for x in range(w):
                            if grid[rr][x] != border:
                                out[rr][x] = color
                # Ray horizontally toward the vertical border on the marker's side.
                edge = ca if c == ca else cb if c == cb else (ca if abs(c-ca) < abs(c-cb) else cb)
                step = 1 if edge == w-1 else -1
                x = c + step
                while 0 <= x < w and grid[r][x] != border:
                    out[r][x] = color
                    x += step
                out[r][c] = 4
            return out

    # Horizontal border runs: extend each top-border column down to the lower run,
    # and extend interior markers vertically toward the lower border.
    by_row = {}
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == border]
        if cs:
            by_row[r] = cs
    if len(by_row) >= 2:
        top, bottom = min(by_row), max(by_row)
        color = markers[0][2] if markers else bg
        for c in by_row[top]:
            for r in range(top + 1, bottom):
                if grid[r][c] != border:
                    out[r][c] = color
        for r, c, color in markers:
            out[r][c] = 4
            for rr in range(r + 1, bottom):
                if grid[rr][c] != border:
                    out[rr][c] = color
    return out
